MM.mnemo[26] = {"cards":[{"id":"ko-k3-0445","w":"듣다","cs":"poslouchat; slyšet","en":"to listen, to hear","p":"v","o":"k","ex":"어디에서 들었어요?","exc":"Kde jsi to slyšel? (에서 → kde)","m":"Nepravidelné časování s ㄷ: před samohláskou se ㄷ mění na ㄹ → 들어요 (poslouchá), 들었어요 (slyšel), ale před souhláskou zůstává → 듣고 (poslouchá a…), 듣습니다.","tv":["들어요","들었어요","들을 거예요"],"irr":"ㄷ"},{"id":"ko-k3-0446","w":"걷다","cs":"jít pěšky; chodit; kráčet","en":"to walk","p":"v","o":"k","ex":"많이 걸었는데, 안 피곤해요.","exc":"Hodně jsem nachodil, ale nejsem unavený.","m":"Nepravidelné časování s ㄷ → 걸어요 (jde pěšky), 걸었어요 (šel pěšky). Pozor: homonymum 걷다 ve významu ‚vyhrnout (rukávy) / vybrat (peníze)‘ se časuje pravidelně (걷어요).","tv":["걸어요","걸었어요","걸을 거예요"],"irr":"ㄷ"},{"id":"ko-k3-0447","w":"묻다","cs":"ptát se; zeptat se","en":"to ask","p":"v","o":"k","ex":"물어도 대답이 없어요.","exc":"I když se ptám, žádná odpověď. (이 → 1. pád)","m":"Nepravidelné časování s ㄷ → 물어요 (ptá se), 물었어요 (zeptal se). Pozor na pravidelné homonymum 묻다 = zakopat / ušpinit se (묻어요). Časté spojení: 물어보다 = zkusit se zeptat.","tv":["물어요","물었어요","물을 거예요"],"irr":"ㄷ"},{"id":"ko-k3-0448","w":"싣다","cs":"naložit; nakládat (náklad, cestující)","en":"to load","p":"v","o":"k","rz":["싣 + 을 거예요 → 실을 거예요","naložit + budoucí čas → naložím"],"m":"Nepravidelné časování s ㄷ → 실어요 (nakládá), 실었어요 (naložil), 실을 거예요 (naloží). Vazba: 차에 짐을 싣다 = naložit zavazadla do auta.","tv":["실어요","실었어요","실을 거예요"],"irr":"ㄷ"},{"id":"ko-k3-0449","w":"깨닫다","cs":"uvědomit si; pochopit; prozřít","en":"to realize","p":"v","o":"k","rz":["깨닫 + 았어요 → 깨달았어요","uvědomit si + minulý čas → uvědomil jsem si"],"m":"Nepravidelné časování s ㄷ → 깨달아요 (uvědomuje si), 깨달았어요 (uvědomil si). Podstatné jméno od tohoto slovesa je 깨달음 (uvědomění, poznání).","tv":["깨달아요","깨달았어요","깨달을 거예요"],"irr":"ㄷ"},{"id":"ko-k3-0450","w":"붇다","cs":"otéct; nabobtnat; zvětšit objem","en":"to swell (up), to be bloated","p":"v","o":"k","rz":["붇다 → 불어요 · 불었어요 · 불을 거예요","otéct / nabobtnat → oteče · otekl · oteče (v budoucnu)"],"m":"Nepravidelné časování s ㄷ → 불어요, 불었어요. Říká se o věcech, které nasákly vodou: rozvařené nudle (라면이 불었어요), namočené fazole. Pozor: oteklý obličej je jiné sloveso 붓다 (얼굴이 부었어요).","tv":["불어요","불었어요","불을 거예요"],"irr":"ㄷ"},{"id":"ko-k3-0451","w":"닫다","cs":"zavřít; zavírat","en":"to close","p":"v","o":"k","rz":["닫 + 으면 → 닫으면","zavřít + když/pokud → když zavřeš"],"m":"Pravidelné sloveso na ㄷ – souhláska ㄷ se nikdy nemění na ㄹ: 닫아요 (zavírá), 닫았어요 (zavřel), 닫으면 (když zavře). Vazba: 문을 닫다 = zavřít dveře. Opak: 열다 (otevřít).","tv":["닫아요","닫았어요","닫을 거예요"]},{"id":"ko-k3-0452","w":"믿다","cs":"věřit; důvěřovat","en":"to believe, to trust","p":"v","o":"k","ex":"그 이야기를 믿어요?","exc":"Věříš tomu příběhu? (를 → 4. pád)","m":"Pravidelné sloveso na ㄷ – ㄷ zůstává i před samohláskou: 믿어요 (věří), 믿었어요 (věřil). Časté spojení: 믿을 수 없어요! = Tomu nemůžu uvěřit!","tv":["믿어요","믿었어요","믿을 거예요"]},{"id":"ko-k3-0453","w":"소리","cs":"zvuk; hluk; hlas","en":"sound, noise","p":"n","o":"k","ex":"방금 소리 들었어요?","exc":"Slyšel jsi teď ten zvuk?","m":"Častá spojení: 소리를 듣다 (slyšet zvuk), 소리가 나다 (ozývá se zvuk), 소리를 지르다 (křičet). Pozor na rozdíl oproti 목소리 = lidský hlas (doslova ‚zvuk krku‘)."},{"id":"ko-k3-0454","w":"방금","cs":"právě teď; před chvilkou; zrovna","en":"just now","p":"o","o":"s","ex":"방금 소리 들었어요?","exc":"Slyšel jsi teď ten zvuk?","m":"方 právě + 今 nyní, teď = právě teď, před okamžikem. Stejné 今 je i ve slově 지금 (teď). Na rozdíl od 아까 (před chvílí, klidně před půl hodinou) označuje 방금 úplný okamžik před několika vteřinami.","r":["bang-方","geum-今"]}],"gram":{"id":"ko-k3-g26","w":"ㄷ 불규칙","en":"Irregulars: ㄷ","cs":"nepravidelná slovesa na ㄷ","vy":"U skupiny nepravidelných sloves končících na ㄷ (např. 듣다, 걷다, 묻다 ve významu ‚ptát se‘, 싣다, 깨닫다) se koncové ㄷ mění na ㄹ, jakmile za ním následuje koncovka začínající samohláskou (např. -어요, -어서, -(으)면, -(으)ㄹ 거예요). Před koncovkou začínající souhláskou (např. -고, -는, -지만) zůstává ㄷ beze změny. Mnoho jiných sloves na ㄷ je však pravidelných a ㄷ si zachovává vždy.","m":"Pozor na dvojí význam slovesa 묻다: ‚ptát se‘ je nepravidelné (물어요 = ptám se), zatímco ‚zakopat / ušpinit se‘ je pravidelné (묻어요 = zakopávám). Pravidelná jsou i běžná slovesa 받다 (dostat), 닫다 (zavřít) a 믿다 (věřit).","s":[["듣 + 어서 → 들어서 · 걷 + 어요 → 걸어요","poslouchat a pak (듣다 → 들어서) · jdu pěšky (걷다 → 걸어요) — před samohláskou se ㄷ mění na ㄹ"],["묻 + 으면 → 물으면 · 싣 + 을 거예요 → 실을 거예요","když se zeptáš (묻다 → 물으면) · naložím (싣다 → 실을 거예요)"],["깨닫 + 았어요 → 깨달았어요","uvědomil jsem si / došlo mi (깨닫다 → 깨달았어요)"],["받아서 · 묻어요 · 닫으면 · 믿어요","dostat a · zakopávám · když zavřeš · věřím (pravidelná slovesa: ㄷ zůstává)"],["물어요. · 묻어요.","Ptám se. · Zakopávám."],["듣고 있어요","Poslouchám. (před souhláskou -고 zůstává ㄷ beze změny)"],["걷는 것 좋아해요","Rád chodím pěšky. (před -는 zůstává ㄷ beze změny)"],["한 시간 걸었어요","Hodinu jsem chodil pěšky."],["어디에서 들었어요?","Kde jsi to slyšel?"],["많이 걸었는데, 안 피곤해요.","Hodně jsem se nachodil, ale nejsem unavený."],["그 이야기를 믿어요?","Věříš tomu příběhu?"],["물어도 대답이 없어요.","I když se ptám, nikdo neodpovídá."],["방금 소리 들었어요?","Slyšel jsi ten zvuk před chvilkou?"],["이상한 소리 못 들었어요?","Neslyšel jsi nějaký divný zvuk?"],["네, 못 들었어요.","Ne, neslyšel."],["붇다 → 불어요 · 불었어요 · 불을 거예요 · 붇고 있어요","bobtnat / otékat (붇다) → bobtná · nabobtnalo · nabobtná · právě bobtná"],["걷는 것을 좋아해서 한 시간 동안 걸었어요.","Rád chodím pěšky, tak jsem se hodinu procházel."]]}};
Object.assign(MM.mnRoots, {"bang-方":["방","方","strana, směr"],"geum-今":["금","今","nyní, teď"]});
